"use client";

import { useState, useEffect, useRef } from "react";

const SECTIONS = [
  "About",
  "Education",
  "Experience",
  "Skills",
  "Projects",
  "Certificates",
  "Publications",
  "Activities",
  "References",
  "Blog",
  "Contact",
];

export default function CodingPanel() {
  const [input, setInput] = useState("");
  const [status, setStatus] = useState("idle"); // idle, error, success
  const inputRef = useRef<HTMLInputElement>(null);

  const handleCommand = (e: React.FormEvent) => {
    e.preventDefault();
    const command = input.trim().toLowerCase();

    // Find matching section
    const targetSection = SECTIONS.find(s => s.toLowerCase() === command);

    if (targetSection) {
      const element = document.getElementById(targetSection.toLowerCase());
      if (element) {
        setStatus("success");
        element.scrollIntoView({ behavior: "smooth" });
        setTimeout(() => {
          setInput("");
          setStatus("idle");
        }, 1000);
      }
    } else {
      setStatus("error");
      setTimeout(() => setStatus("idle"), 1000);
    }
  };

  return (
    <div className={`coding-panel-container coding-panel-responsive ${status}`} style={{
      marginTop: "48px",
      width: "100%",
      maxWidth: "650px", // Increased from 500px
      marginInline: "auto",
      fontFamily: "'Fira Code', 'Courier New', monospace",
      position: "relative",
      zIndex: 10,
    }}>
      {/* Mac Terminal Window */}
      <div style={{
        overflow: "hidden",
        background: "var(--bg-card)",
        backdropFilter: "blur(20px)",
        WebkitBackdropFilter: "blur(20px)",
        border: "1px solid var(--glass-border)",
        boxShadow: status === "error" ? "0 0 40px rgba(239, 68, 68, 0.2)" : (status === "success" ? "0 0 40px rgba(74, 222, 128, 0.2)" : "0 20px 50px rgba(0, 0, 0, 0.15)"),
        borderRadius: "12px",
        transition: "all 0.4s cubic-bezier(0.4, 0, 0.2, 1)",
      }}>
        {/* Terminal Header (Title Bar) */}
        <div style={{
          height: "36px",
          background: "rgba(128, 128, 128, 0.08)",
          display: "flex",
          alignItems: "center",
          padding: "0 16px",
          borderBottom: "1px solid rgba(255, 255, 255, 0.05)",
          position: "relative",
        }}>
          {/* Traffic Light Buttons */}
          <div style={{ display: "flex", gap: "8px" }}>
            <div style={{ width: "12px", height: "12px", borderRadius: "50%", background: "#ff5f56" }}></div>
            <div style={{ width: "12px", height: "12px", borderRadius: "50%", background: "#ffbd2e" }}></div>
            <div style={{ width: "12px", height: "12px", borderRadius: "50%", background: "#27c93f" }}></div>
          </div>

          {/* Title */}
          <div style={{
            position: "absolute",
            left: "50%",
            transform: "translateX(-50%)",
            fontSize: "12px",
            color: "var(--text-primary)",
            opacity: 0.4,
            letterSpacing: "0.02em",
            fontWeight: 500,
            whiteSpace: "nowrap",
          }}>
            mirazul — -zsh — 80x24
          </div>
        </div>

        {/* Terminal Body */}
        <form className="terminal-form-inner" onSubmit={handleCommand} style={{
          display: "flex",
          alignItems: "center",
          padding: "24px", // Increased padding
          gap: "12px",
          transition: "all 0.3s ease",
          transform: status === "error" ? "translateX(5px)" : "none",
        }}>
          {/* Desktop Full Prompt */}
          <div className="terminal-prompt terminal-prompt-full" style={{
            display: "flex",
            gap: "8px",
            color: "var(--accent)",
            fontWeight: "bold",
            fontSize: "15px", // Slightly larger font
            whiteSpace: "nowrap",
            userSelect: "none"
          }}>
            <span style={{ color: "#4ade80" }}>mirazul</span>
            <span style={{ color: "var(--text-muted)" }}>@</span>
            <span style={{ color: "var(--accent)" }}>macbook</span>
            <span style={{ color: "var(--text-muted)" }}>:</span>
            <span style={{ color: "#f472b6" }}>~</span>
            <span style={{ color: "var(--text-muted)" }}>$</span>
          </div>

          {/* Mobile Short Prompt */}
          <div className="terminal-prompt terminal-prompt-short" style={{
            display: "none", // Hidden by default, shown via media query
            gap: "4px",
            color: "var(--accent)",
            fontWeight: "bold",
            fontSize: "13px",
            whiteSpace: "nowrap",
            userSelect: "none"
          }}>
            <span style={{ color: "#f472b6" }}>~</span>
            <span style={{ color: "var(--text-muted)" }}>$</span>
          </div>

          <input
            ref={inputRef}
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="Type command to navigate..."
            style={{
              background: "transparent",
              border: "none",
              outline: "none",
              color: status === "error" ? "#ef4444" : "var(--text-primary)",
              fontSize: "15px",
              width: "100%",
              caretColor: "var(--accent)",
              letterSpacing: "0.02em",
            }}
            autoComplete="off"
            spellCheck="false"
          />

          <div style={{
            fontSize: "11px",
            color: "var(--text-primary)",
            opacity: 0.5,
            whiteSpace: "nowrap",
            textTransform: "uppercase",
            letterSpacing: "0.1em",
            fontFamily: "Inter, sans-serif"
          }}>
            ⏎ Enter
          </div>
        </form>
      </div>

      {/* Quick Links Overlay (Kept as requested) */}
      <div style={{
        display: "flex",
        justifyContent: "center",
        flexWrap: "wrap",
        gap: "12px",
        marginTop: "20px",
        opacity: 0.6
      }}>
        {SECTIONS.map((s) => (
          <span 
            key={s} 
            onClick={() => {
              setInput(s);
              inputRef.current?.focus();
            }}
            className="quick-link-tag"
            style={{
              fontSize: "11px",
              padding: "4px 12px",
              background: "rgba(255,255,255,0.03)",
              borderRadius: "50px",
              cursor: "pointer",
              transition: "all 0.3s",
              border: "1px solid var(--border)",
              color: "var(--text-primary)",
              opacity: 0.8,
              fontWeight: 600,
            }}
          >
            {s}
          </span>
        ))}
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect, useRef } from "react";
import Link from "next/link";
import {
  ChevronDown, Menu, X, User, Briefcase, Code, GraduationCap,
  LayoutPanelLeft, FileText, Mail, Settings, Award, BookOpen, Star, Sparkles
} from "lucide-react";
import ThemeToggle from "./ThemeToggle";
import { motion, AnimatePresence } from "framer-motion";

interface NavbarProps {
  profile: any;
}

const PRIMARY_LINKS = [
  { name: "About", href: "#about", icon: <User size={14} /> },
  { name: "Education", href: "#education", icon: <GraduationCap size={14} /> },
  { name: "Experience", href: "#experience", icon: <Briefcase size={14} /> },
  { name: "Skills", href: "#skills", icon: <Code size={14} /> },
  { name: "Projects", href: "#projects", icon: <LayoutPanelLeft size={14} /> },
];

const SECONDARY_LINKS = [
  { name: "Certificates", href: "#certificates", icon: <Award size={14} /> },
  { name: "Publications", href: "#publications", icon: <BookOpen size={14} /> },
  { name: "Activities", href: "#activities", icon: <Sparkles size={14} /> },
  { name: "References", href: "#references", icon: <Star size={14} /> },
  { name: "Blog", href: "#blog", icon: <FileText size={14} /> },
  { name: "Contact", href: "#contact", icon: <Mail size={14} /> },
];

export default function Navbar({ profile }: NavbarProps) {
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [isMobileOpen, setIsMobileOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };

    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, []);

  const closeMenus = () => {
    setIsDropdownOpen(false);
    setIsMobileOpen(false);
  };

  return (
    <>
      <div className="navbar-container">
        <nav className="navbar-pill">
          {/* Logo */}
          <Link href="/" className="nav-logo-link" style={{ display: "flex", alignItems: "center", marginRight: "8px" }}>
            <div className="logo-container" style={{
              width: 32,
              height: 32,
              borderRadius: "50%",
              background: "linear-gradient(135deg, #6c63ff, #ff6584)",
              padding: "1.5px"
            }}>
              <div style={{ width: "100%", height: "100%", borderRadius: "50%", overflow: "hidden", background: "var(--avatar-bg)" }}>
                <img src={profile?.avatarUrl || "/logo.png"} alt="Logo" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
              </div>
            </div>
          </Link>

          {/* Desktop Nav Links */}
          <div className="nav-links-main">
            {PRIMARY_LINKS.map((link) => (
              <Link key={link.name} href={link.href} className="nav-link-item" style={{ display: "flex", alignItems: "center", gap: "8px" }}>
                <span style={{ opacity: 0.8, display: "flex", color: "var(--accent)" }}>{link.icon}</span>
                {link.name}
              </Link>
            ))}

            {/* More Dropdown */}
            <div ref={dropdownRef} className="nav-dropdown-wrapper">
              <button
                className={`nav-dropdown-trigger ${isDropdownOpen ? 'active' : ''}`}
                onClick={() => setIsDropdownOpen(!isDropdownOpen)}
              >
                More <ChevronDown size={14} style={{ transform: isDropdownOpen ? 'rotate(180deg)' : 'none', transition: 'transform 0.3s' }} />
              </button>

              <AnimatePresence>
                {isDropdownOpen && (
                  <motion.div
                    initial={{ opacity: 0, y: 10, scale: 0.95 }}
                    animate={{ opacity: 1, y: 0, scale: 1 }}
                    exit={{ opacity: 0, y: 10, scale: 0.95 }}
                    className={`nav-dropdown-menu visible`}
                  >
                    {SECONDARY_LINKS.map((link) => (
                      <Link
                        key={link.name}
                        href={link.href}
                        className="dropdown-item"
                        onClick={() => setIsDropdownOpen(false)}
                      >
                        <span style={{ color: "var(--accent)" }}>{link.icon}</span>
                        {link.name}
                      </Link>
                    ))}
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
          </div>

          <div className="nav-divider" />

          {/* Actions */}
          <div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
            <ThemeToggle />

            <Link href="/login" className="nav-cta">
              <span className="desktop-only" style={{ display: "flex", alignItems: "center", gap: "6px" }}>
                <Settings size={14} /> Admin
              </span>
            </Link>

            {/* Mobile Toggle */}
            <button className="mobile-toggle" onClick={() => setIsMobileOpen(true)}>
              <Menu size={24} />
            </button>
          </div>
        </nav>
      </div>

      {/* Mobile Overlay */}
      <div className={`mobile-overlay ${isMobileOpen ? 'open' : ''}`}>
        <button className="close-mobile" onClick={() => setIsMobileOpen(false)}>
          <X size={32} />
        </button>

        <div className="mobile-nav-links">
          {/* Logo link for mobile home navigation */}
          <Link href="/" onClick={closeMenus} style={{ marginBottom: "20px" }}>
            <div className="logo-container" style={{
              width: 80,
              height: 80,
              borderRadius: "50%",
              background: "linear-gradient(135deg, #6c63ff, #ff6584)",
              padding: "4px"
            }}>
              <div style={{ width: "100%", height: "100%", borderRadius: "50%", overflow: "hidden", background: "var(--avatar-bg)" }}>
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img src={profile?.avatarUrl || "/logo.png"} alt="Logo" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
              </div>
            </div>
          </Link>

          <div className="mobile-nav-grid">
            {[...PRIMARY_LINKS, ...SECONDARY_LINKS].map((link) => (
              <Link key={link.name} href={link.href} className="mobile-nav-item" onClick={closeMenus} style={{
                display: "flex",
                alignItems: "center",
                gap: "12px",
              }}>
                <span style={{ color: "var(--accent)" }}>{link.icon}</span>
                {link.name}
              </Link>
            ))}
          </div>

          <Link href="/login" className="mobile-nav-item" onClick={closeMenus} style={{ color: "var(--accent)", marginTop: "40px" }}>
            Admin Dashboard
          </Link>
        </div>
      </div>
    </>
  );
}

"use client";
import { motion, AnimatePresence } from "framer-motion";
import { Mail, MapPin, Calendar, CheckCircle, Link as LinkIcon, Edit2, Star, Trophy, Zap, Lightbulb, Github, Linkedin, Facebook, Instagram, Youtube, Twitter } from "lucide-react";

export default function AtsResume({ profile, education, experience, skills, certificates, activities, publications, references }: any) {
    // Collect initials for the avatar placeholder
    const getInitials = (name: string) => {
        if (!name) return "MM";
        return name.split(" ").map(n => n[0]).join("").substring(0, 2).toUpperCase();
    };

    const getSocialIcon = (platform: string) => {
        const p = platform.toLowerCase();
        if (p.includes('github')) return <Github size={12} color="#007bff" />;
        if (p.includes('linkedin')) return <Linkedin size={12} color="#007bff" />;
        if (p.includes('facebook')) return <Facebook size={12} color="#007bff" />;
        if (p.includes('instagram')) return <Instagram size={12} color="#007bff" />;
        if (p.includes('youtube')) return <Youtube size={12} color="#007bff" />;
        if (p.includes('twitter') || p.includes(' x ')) return <Twitter size={12} color="#007bff" />;
        return <LinkIcon size={12} color="#007bff" />;
    };

    return (
        <div id="ats-cv" className="ats-resume">
            <style>{`
                .ats-resume {
                    display: none;
                }
                @media print {
                    html, body {
                        background: #fff !important;
                        background-color: #fff !important;
                        color: #000 !important;
                        margin: 0 !important;
                        padding: 0 !important;
                        height: auto !important;
                    }
                    .ats-resume {
                        display: block !important;
                        background: #fff !important;
                        color: #000 !important;
                        font-family: Arial, "Helvetica Neue", Helvetica, sans-serif !important;
                        line-height: 1.25;
                        padding: 0;
                        margin: 0;
                        width: 100%;
                        position: static !important;
                        overflow: visible !important;
                    }

                    /* Page Settings */
                    @page { 
                        size: A4 portrait; 
                        margin: 15mm 15mm; 
                    }

                    /* Global Overrides */
                    .ats-resume * {
                        box-sizing: border-box;
                    }

                    /* Top Header Grid */
                    .ats-header-grid {
                        display: grid;
                        grid-template-columns: 1fr auto;
                        gap: 12pt;
                        align-items: center;
                        margin-bottom: 16pt;
                    }

                    .ats-name { font-size: 26pt; font-weight: 800; margin: 0 0 4pt 0; text-transform: uppercase; color: #000; letter-spacing: 0.5px; }
                    .ats-title { font-size: 13pt; font-weight: 700; margin: 0 0 8pt 0; text-transform: uppercase; color: #007bff !important; letter-spacing: 0.2px; }

                    .ats-contact-row { display: flex; flex-wrap: wrap; gap: 12pt; font-size: 9.5pt; color: #444; font-weight: 600; align-items: center; }
                    .ats-contact-item { display: flex; align-items: center; gap: 4pt; }
                    .ats-contact-item a { color: inherit; text-decoration: none; }
                    .ats-contact-item a:hover { text-decoration: underline; }

                    .ats-avatar-circle {
                        width: 100pt;
                        height: 100pt;
                        border-radius: 50%;
                        background-color: #0084ff !important;
                        color: #000 !important;
                        display: flex;
                        align-items: center;
                        justify-content: center;
                        font-size: 28pt;
                        font-weight: 800;
                        -webkit-print-color-adjust: exact !important;
                        print-color-adjust: exact !important;
                        overflow: hidden;
                        margin-right: 15pt;
                    }
                    .ats-avatar-circle img {
                        width: 100%;
                        height: 100%;
                        object-fit: cover;
                    }

                    /* Main Split Layout */
                    .ats-body-grid {
                        display: block;
                    }

                    /* Sections */
                    .ats-section { margin-bottom: 12pt; page-break-inside: avoid; }
                    .ats-section-title { 
                        font-size: 13pt; 
                        font-weight: 800; 
                        text-transform: uppercase; 
                        border-bottom: 2.5px solid #000; 
                        margin-bottom: 6pt; 
                        padding-bottom: 1pt; 
                        color: #000;
                    }

                    /* Custom Divider between items */
                    .ats-item { 
                        padding-bottom: 6pt;
                        margin-bottom: 6pt;
                        border-bottom: 1px dotted #ccc;
                        page-break-inside: avoid; 
                    }
                    .ats-item:last-child {
                        border-bottom: none;
                        padding-bottom: 0;
                        margin-bottom: 0;
                    }

                    /* Typography details */
                    .ats-item-title { font-weight: 800; font-size: 11.5pt; color: #000; margin-bottom: 2pt; line-height: 1.2; }
                    .ats-item-subtitle { font-weight: 700; font-size: 10pt; color: #007bff !important; margin-bottom: 2pt; }
                    .ats-item-date { font-size: 9pt; color: #777; display: flex; align-items: center; gap: 4pt; margin-bottom: 2pt; font-weight: 500; }

                    .ats-resume p { font-size: 9.5pt; color: #444; margin: 0 0 2pt 0; text-align: justify; line-height: 1.25; }
                    .ats-resume ul { font-size: 9.5pt; color: #444; margin: 0 0 0 15pt; padding: 0; list-style-type: disc; }
                    .ats-resume li { margin-bottom: 1pt; text-align: justify; }

                    /* Skills specific */
                    .ats-skill-tag {
                        display: inline-block;
                        border-bottom: 1.5px solid #888;
                        padding-bottom: 2pt;
                        margin-right: 12pt;
                        margin-bottom: 6pt;
                        font-size: 9pt;
                        font-weight: 700;
                        color: #333;
                    }

                    .ats-interest-item {
                        display: flex;
                        gap: 6pt;
                        align-items: flex-start;
                        margin-bottom: 4pt;
                    }
                }
            `}</style>

            {/* HEADER */}
            <div className="ats-header-grid">
                <div>
                    <h1 className="ats-name">{profile?.name || "MD. MIRAZUL HASAN"}</h1>
                    <h2 className="ats-title">{profile?.title || "AI ENGINEER, AI AGENT AUTOMATION"}</h2>

                    <div className="ats-contact-row">
                        {profile?.email && (
                            <div className="ats-contact-item">
                                <Mail size={12} color="#007bff" />
                                <a href={`mailto:${profile.email}`}>{profile.email}</a>
                            </div>
                        )}
                    </div>
                    <div className="ats-contact-row" style={{ marginTop: '4pt' }}>
                        {profile?.address && (
                            <div className="ats-contact-item">
                                <MapPin size={12} color="#007bff" />
                                <span>{profile.address}</span>
                            </div>
                        )}
                    </div>
                    {profile?.socialLinks?.length > 0 && (
                        <div className="ats-contact-row" style={{ marginTop: '4pt' }}>
                            {profile.socialLinks.map((l: any, idx: number) => (
                                <div key={idx} className="ats-contact-item">
                                    {getSocialIcon(l.platform)}
                                    <a href={l.url} target="_blank" rel="noopener noreferrer">{l.platform}</a>
                                </div>
                            ))}
                        </div>
                    )}
                </div>

                <div className="ats-avatar-circle">
                    {profile?.avatarUrl ? (
                        <img src={profile.avatarUrl} alt="Profile" />
                    ) : (
                        getInitials(profile?.name)
                    )}
                </div>
            </div>

            {/* SINGLE COLUMN BODY */}
            <div className="ats-body-grid">

                {/* SUMMARY */}
                {(profile?.bio || profile?.aboutTitle) && (
                    <div className="ats-section">
                        <div className="ats-section-title">Summary</div>
                        <p>{profile?.bio || "Passionate about developing innovative solutions."}</p>
                    </div>
                )}

                {/* EXPERIENCE */}
                {experience?.length > 0 && (
                    <div className="ats-section">
                        <div className="ats-section-title">Experience</div>
                        {experience.sort((a: any, b: any) => new Date(b.startDate).getTime() - new Date(a.startDate).getTime()).map((exp: any) => (
                            <div key={exp.id} className="ats-item">
                                <div className="ats-item-title">{!exp.current ? `Former ${exp.position}` : exp.position}</div>
                                <div className="ats-item-subtitle">{exp.company}</div>
                                <div className="ats-item-date">
                                    <Calendar size={11} color="#777" />
                                    {new Date(exp.startDate).toLocaleDateString('en-US', { month: '2-digit', year: 'numeric' })} -
                                    {exp.current ? " Present" : exp.endDate ? ` ${new Date(exp.endDate).toLocaleDateString('en-US', { month: '2-digit', year: 'numeric' })}` : ""}
                                </div>
                                {exp.description && (
                                    <p>{exp.description.replace(/^[-\*]\s*/gm, '')}</p>
                                )}
                            </div>
                        ))}
                    </div>
                )}

                {/* EDUCATION */}
                {education?.length > 0 && (
                    <div className="ats-section">
                        <div className="ats-section-title">Education</div>
                        {education.sort((a: any, b: any) => {
                            // Prioritize MS in CS or anything with "Master" as the latest
                            const aIsMaster = a.degree?.toLowerCase().includes("master");
                            const bIsMaster = b.degree?.toLowerCase().includes("master");
                            if (aIsMaster && !bIsMaster) return -1;
                            if (!aIsMaster && bIsMaster) return 1;

                            // Otherwise sort by date
                            const aDate = new Date(a.startDate || a.passingYear || 0).getTime();
                            const bDate = new Date(b.startDate || b.passingYear || 0).getTime();
                            return bDate - aDate;
                        }).map((edu: any) => (
                            <div key={edu.id} className="ats-item">
                                <div className="ats-item-title">{edu.degree}{edu.field ? ` in ${edu.field}` : ""}</div>
                                <div className="ats-item-subtitle">{edu.school}</div>
                                <div className="ats-item-date">
                                    <Calendar size={11} color="#777" />
                                    {edu.current ? "Present" : (edu.passingYear || "Ongoing")}
                                </div>
                                {edu.grade && <p>{edu.gradeType}: {edu.grade} {edu.gradeScale ? `/ ${edu.gradeScale}` : ""}</p>}
                            </div>
                        ))}
                    </div>
                )}

                {/* SKILLS */}
                {skills?.length > 0 && (
                    <div className="ats-section">
                        <div className="ats-section-title">Skills</div>
                        <div style={{ display: 'flex', flexWrap: 'wrap' }}>
                            {/* Flatten all skills across categories to closely match the image */}
                            {skills.map((skill: any) => (
                                <span key={skill.id} className="ats-skill-tag">
                                    {skill.name}
                                </span>
                            ))}
                        </div>
                    </div>
                )}

                {/* CERTIFICATIONS */}
                {certificates?.length > 0 && (
                    <div className="ats-section">
                        <div className="ats-section-title">Certifications</div>
                        {certificates.map((cert: any) => (
                            <div key={cert.id} className="ats-item">
                                <div className="ats-item-title" style={{ fontSize: '10.5pt' }}>{cert.title}</div>
                                <div className="ats-resume" style={{ display: 'block', fontSize: '9pt', color: '#666' }}>{cert.issuer}</div>
                            </div>
                        ))}
                    </div>
                )}

                {/* RESEARCH PAPERS (Publications) */}
                {publications?.length > 0 && (
                    <div className="ats-section">
                        <div className="ats-section-title">Research Papers</div>
                        {publications.map((pub: any, index: number) => (
                            <div key={pub.id} className="ats-interest-item ats-item" style={{ borderBottom: '1px dotted #ccc', paddingBottom: '6pt', marginBottom: '6pt' }}>
                                <div style={{ marginTop: '2pt' }}>
                                    {index === 0 ? <Edit2 size={13} color="#0084ff" /> : index === 1 ? <Star size={14} color="#0084ff" /> : <Trophy size={14} color="#0084ff" />}
                                </div>
                                <div style={{ flex: 1 }}>
                                    <div className="ats-item-title" style={{ fontSize: '10pt', marginBottom: '1pt' }}>{pub.title} {pub.submitted && "(Submitted)"}</div>
                                    <div style={{ fontSize: '9pt', color: '#666', lineHeight: 1.25 }}>{pub.publisher}</div>
                                    {pub.date && new Date(pub.date).getUTCFullYear() !== 1970 && (
                                        <div className="ats-item-date" style={{ marginTop: '3pt', marginBottom: 0 }}>
                                            {new Date(pub.date).getFullYear()}
                                        </div>
                                    )}
                                </div>
                            </div>
                        ))}
                    </div>
                )}

                {/* EXTRA CURRICULAR ACTIVITIES */}
                {activities?.length > 0 && (
                    <div className="ats-section">
                        <div className="ats-section-title">Extra Curricular Activities</div>
                        {activities.map((act: any, index: number) => (
                            <div key={act.id} className="ats-interest-item ats-item" style={{ borderBottom: '1px dotted #ccc', paddingBottom: '6pt', marginBottom: '6pt' }}>
                                <div style={{ marginTop: '2pt' }}>
                                    {index === 0 ? <Zap size={14} color="#0084ff" /> : index === 1 ? <Lightbulb size={14} color="#0084ff" /> : index === 2 ? <Trophy size={14} color="#0084ff" /> : <CheckCircle size={14} color="#0084ff" />}
                                </div>
                                <div style={{ flex: 1 }}>
                                    <div className="ats-item-title" style={{ fontSize: '10pt', marginBottom: '1pt' }}>{!act.current ? "Former " : ""}{act.role || act.title}</div>
                                    <div style={{ fontSize: '9pt', color: '#666', lineHeight: 1.25 }}>{act.role ? act.title : act.description}</div>
                                </div>
                            </div>
                        ))}
                    </div>
                )}

                {/* REFERENCES */}
                {references?.length > 0 && (
                    <div className="ats-section">
                        <div className="ats-section-title">References</div>
                        {references.map((ref: any) => (
                            <div key={ref.id} className="ats-item">
                                <div className="ats-item-title" style={{ fontSize: '10.5pt' }}>{ref.name}</div>
                                <div style={{ fontSize: '9pt', color: '#444', fontWeight: 600 }}>{ref.designation}</div>
                                {ref.company && <div style={{ fontSize: '9pt', color: '#666' }}>{ref.company}</div>}
                                {ref.email && <div style={{ fontSize: '9pt', color: '#007bff' }}><a href={`mailto:${ref.email}`} style={{ color: 'inherit', textDecoration: 'none' }}>{ref.email}</a></div>}
                            </div>
                        ))}
                    </div>
                )}

            </div>
        </div>
    );
}

"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { signOut } from "next-auth/react";
import { useEffect, useState } from "react";
import ThemeToggle from "@/components/ThemeToggle";

const navigation = [
    { name: "Dashboard", href: "/admin", icon: "⚡" },
    { name: "About", href: "/admin/profile", icon: "👤" },
    { name: "Education", href: "/admin/education", icon: "🎓" },
    { name: "Experience", href: "/admin/experience", icon: "💼" },
    { name: "Projects", href: "/admin/projects", icon: "🚀" },
    { name: "Skills", href: "/admin/skills", icon: "🧠" },
    { name: "Certificates", href: "/admin/certificates", icon: "📜" },
    { name: "Activities", href: "/admin/activities", icon: "🏅" },
    { name: "Publications", href: "/admin/publications", icon: "📚" },
    { name: "References", href: "/admin/references", icon: "🤝" },
    { name: "Blog Posts", href: "/admin/posts", icon: "✍️" },
];

export function Sidebar() {
    const pathname = usePathname();
    const [profile, setProfile] = useState<any>(null);

    useEffect(() => {
        fetch("/api/profile")
            .then((r) => r.json())
            .then(setProfile)
            .catch(() => { });
    }, []);

    // Re-fetch whenever we navigate to pick up a fresh avatar
    useEffect(() => {
        fetch("/api/profile")
            .then((r) => r.json())
            .then(setProfile)
            .catch(() => { });
    }, [pathname]);

    const initials = (profile?.name ?? "M").charAt(0).toUpperCase();

    return (
        <div className="hide-on-print" style={{
            width: 260,
            minHeight: "100vh",
            background: "var(--bg-nav)",
            backdropFilter: "blur(24px)",
            borderRight: "1px solid var(--border)",
            display: "flex",
            flexDirection: "column",
            position: "fixed",
            top: 0,
            left: 0,
            bottom: 0,
            zIndex: 40,
        }}>
            {/* ── Brand header ── */}
            <div style={{ padding: "28px 24px 20px", borderBottom: "1px solid var(--border)" }}>
                <Link href="/admin" style={{ textDecoration: "none" }}>
                    <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 20 }}>
                        <div style={{ color: "var(--text-primary)", width: 30, height: 30, borderRadius: 8, background: "linear-gradient(135deg, #6c63ff, #ff6584)", display: "flex", alignItems: "center", justifyContent: "center", fontWeight: 900, fontSize: 16 }}>{initials}</div>
                        <span className="gradient-text" style={{ fontWeight: 800, fontSize: "1rem" }}>Admin Portal</span>
                    </div>
                </Link>

                {/* ── Avatar ── */}
                <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
                    <div style={{
                        width: 52, height: 52, borderRadius: "50%",
                        background: "linear-gradient(135deg, #6c63ff, #ff6584)",
                        padding: 2, flexShrink: 0,
                        boxShadow: "0 0 20px rgba(108,99,255,0.4)",
                    }}>
                        <div style={{ width: "100%", height: "100%", borderRadius: "50%", overflow: "hidden", background: "var(--avatar-bg)" }}>
                            {profile?.avatarUrl ? (
                                <img src={profile.avatarUrl} alt="avatar" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                            ) : (
                                <div style={{ width: "100%", height: "100%", display: "flex", alignItems: "center", justifyContent: "center", fontWeight: 800, fontSize: 20, color: "var(--text-primary)" }}>
                                    {initials}
                                </div>
                            )}
                        </div>
                    </div>
                    <div style={{ minWidth: 0 }}>
                        <p style={{ fontWeight: 700, fontSize: 14, color: "var(--text-primary)", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
                            {profile?.name || "Admin"}
                        </p>
                        <p style={{ fontSize: 11, color: "var(--text-muted)", marginTop: 2, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
                            {profile?.title || "Administrator"}
                        </p>
                    </div>
                </div>
            </div>

            {/* ── Navigation ── */}
            <nav style={{ flex: 1, padding: "16px 12px", display: "flex", flexDirection: "column", gap: 4 }}>
                {navigation.map((item) => {
                    const isActive = pathname === item.href;
                    return (
                        <Link key={item.href} href={item.href} style={{
                            padding: "10px 14px",
                            borderRadius: 10,
                            textDecoration: "none",
                            color: isActive ? "var(--text-primary)" : "var(--text-muted)",
                            fontSize: 13,
                            fontWeight: 600,
                            background: isActive ? "rgba(108, 99, 255, 0.15)" : "transparent",
                            border: isActive ? "1px solid rgba(108, 99, 255, 0.3)" : "1px solid transparent",
                            transition: "all 0.18s ease",
                            display: "flex",
                            alignItems: "center",
                            gap: 10,
                        }}>
                            <span style={{ fontSize: 15, width: 20, textAlign: "center" }}>{item.icon}</span>
                            {item.name}
                        </Link>
                    );
                })}
            </nav>

            {/* ── Footer ── */}
            <div style={{ padding: "16px 12px", borderTop: "1px solid var(--border)", display: "flex", flexDirection: "column", gap: 8 }}>
                {/* View portfolio */}
                <Link href="/" target="_blank" style={{
                    padding: "10px 14px", borderRadius: 10, textDecoration: "none",
                    color: "var(--text-muted)", fontSize: 13, fontWeight: 600,
                    border: "1px solid var(--border)", transition: "all 0.18s",
                    display: "flex", alignItems: "center", gap: 10,
                }}>
                    <span style={{ fontSize: 15 }}>🌐</span> View Portfolio
                </Link>
                {/* Sign out */}
                <button onClick={() => signOut({ callbackUrl: "/login" })} style={{
                    width: "100%", padding: "10px 14px", borderRadius: 10,
                    border: "1px solid rgba(220, 38, 38, 0.2)",
                    background: "rgba(220, 38, 38, 0.05)", cursor: "pointer",
                    color: "#ff4d4d", fontSize: 13, fontWeight: 600,
                    display: "flex", alignItems: "center", gap: 10,
                    transition: "all 0.18s",
                }}
                    onMouseEnter={(e) => { e.currentTarget.style.background = "rgba(220,38,38,0.15)"; }}
                    onMouseLeave={(e) => { e.currentTarget.style.background = "rgba(220,38,38,0.05)"; }}
                >
                    <span style={{ fontSize: 15 }}>🚪</span> Sign Out
                </button>
                {/* Theme Toggle in Admin Panel */}
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "8px 14px", marginTop: 8 }}>
                    <span style={{ fontSize: 13, fontWeight: 600, color: "var(--text-muted)" }}>Theme</span>
                    <ThemeToggle />
                </div>
            </div>
        </div>
    );
}
